import datetime
try:
    b = config.get('body')
    if isinstance(b, dict):
        a = str(b.get('amount_cents') or '').replace(',', '').strip()
        if '.' in a:
            b['amount_cents'] = int(round(float(a) * 100))
        elif a:
            b['amount_cents'] = int(round(float(a)))
        m = re.search(r'\d{4}-\d{2}-\d{2}', str(b.get('date') or ''))
        if m:
            b['date'] = m.group(0)
        ref = str(b.get('account_ref') or '')
        q = [x for x in str(vars.get('promise_ref_queue') or '').split(',') if x]
        q.append(ref)
        vars['promise_ref_queue'] = ','.join(q)
        lim = json.loads(vars.get('limits_json') or '{}')
        p = lim.get('p', dict()).get(ref)
        msg = ''
        if p:
            hol = set(lim.get('hol') or [])
            today = datetime.date.fromisoformat(lim['today'])
            dl = datetime.date.fromisoformat(p['deadline'])
            try:
                d = datetime.date.fromisoformat(str(b.get('date'))[:10])
            except Exception:
                d = None
            if d is None:
                msg = 'The date could not be read. Ask for the exact day.'
            elif d < today:
                msg = 'That date is in the past. Ask for a date from today to ' + p['deadline_spoken'] + '.'
            elif d.weekday() >= 5 or d.isoformat() in hol:
                nb = d + datetime.timedelta(days=1)
                while nb.weekday() >= 5 or nb.isoformat() in hol:
                    nb = nb + datetime.timedelta(days=1)
                msg = ('That day is not a business day. Offer the next business day, ' + nb.isoformat() + ', instead.') if nb <= dl else ('Say: The latest date I can record for your ' + p['label'] + ' is ' + p['deadline_spoken'] + '. Could you pay on that day?')
            elif d > dl:
                msg = 'Say: The latest date I can record for your ' + p['label'] + ' is ' + p['deadline_spoken'] + '. Could you pay on that day?'
            amt = int(b.get('amount_cents') or 0)
            if amt < int(p['floor']):
                msg = msg + ' Say: I cannot record less than ' + p['floor_text'] + ' for your ' + p['label'] + '. Could you pay ' + p['floor_text'] + '? The rest stays overdue.'
            elif amt > int(p['past']):
                msg = msg + ' The amount is more than the full past-due amount ' + p['past_text'] + '; use at most that.'
        if msg:
            vars['promise_block'] = msg.strip()
            b.pop('date', None)
            b.pop('amount_cents', None)
except Exception:
    pass
