     "code": {"type": "string", "default": "import datetime
import json

WEEKDAYS = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
MONTHS = ['january', 'february', 'march', 'april', 'may', 'june', 'july', 'august', 'september', 'october', 'november', 'december']

def parse_now(value):
    s = str(value or '').strip().replace(' ', 'T').rstrip('Z')
    for fmt, size in (('%Y-%m-%dT%H:%M:%S', 19), ('%Y-%m-%dT%H:%M', 16), ('%Y-%m-%d', 10)):
        try:
            return datetime.datetime.strptime(s[:size], fmt)
        except ValueError:
            pass
    raise ValueError('cannot read now: ' + s)

def parse_holidays(values):
    out = set()
    for v in values or []:
        try:
            out.add(datetime.date.fromisoformat(str(v)[:10]))
        except ValueError:
            pass
    return out

def is_business_day(d, holidays):
    return d.weekday() < 5 and d not in holidays

def next_business_day(d, holidays, include_today=False):
    if include_today and is_business_day(d, holidays):
        return d
    d = d + datetime.timedelta(days=1)
    while not is_business_day(d, holidays):
        d = d + datetime.timedelta(days=1)
    return d

def add_business_days(d, n, holidays):
    for _ in range(int(n)):
        d = next_business_day(d, holidays)
    return d

def week_monday(d):
    return d - datetime.timedelta(days=d.weekday())

def last_business_day_of_week(d, holidays):
    day = week_monday(d) + datetime.timedelta(days=4)
    while day >= week_monday(d):
        if is_business_day(day, holidays):
            return day
        day = day - datetime.timedelta(days=1)
    return None

def spoken_date(d):
    return WEEKDAYS[d.weekday()].title() + ' ' + str(d.day) + ' ' + MONTHS[d.month - 1].title()

def to_cents(amount):
    return int(round(float(str(amount).replace(',', '')) * 100))

def money(amount):
    v = round(float(amount), 2)
    return '{:,.0f}'.format(v) if v == int(v) else '{:,.2f}'.format(v)

def as_list(value):
    if isinstance(value, list):
        return value
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except ValueError:
            return []
    if isinstance(value, dict):
        return [value]
    return value if isinstance(value, list) else []

def list_from_vars(vars, name, prefixes):
    found = as_list(vars.get(name)) if vars.get(name) not in (None, '') else []
    if found:
        return found
    for prefix in prefixes:
        rows = {}
        start = prefix + '.'
        for key, value in vars.items():
            if not str(key).startswith(start):
                continue
            rest = str(key)[len(start):]
            idx, _, field = rest.partition('.')
            if idx.isdigit():
                if field:
                    rows.setdefault(int(idx), {})[field] = value
                else:
                    rows[int(idx)] = value
        if rows:
            return [rows[i] for i in sorted(rows)]
        whole = vars.get(prefix)
        if whole not in (None, ''):
            got = as_list(whole)
            if got:
                return got
    return []

HOL = ['2026-10-12', '2026-11-11', '2026-11-26', '2026-11-27', '2026-12-25']
BANDS = [(1, 9, 11, 1, 'early'), (10, 50, 6, 2, 'late')]
try:
    now = parse_now(vars.get('now'))
    hol = parse_holidays(HOL)
    today = now.date()
    items = list_from_vars(vars, 'products', ['load_account_response.data.products', 'get_account_response.data.products'])
    week_end = last_business_day_of_week(today, hol)
    if week_end is None or week_end <= today:
        week_end = last_business_day_of_week(today + datetime.timedelta(days=7), hol)
    blocks, stmt, deadlines = [], [], []
    lim = dict()
    for n, it in enumerate(items, 1):
        typ = str(it.get('type') or '')
        days = int(float(it.get('days_late') or 0))
        band = BANDS[0] if days <= 9 else BANDS[1]
        deadline = add_business_days(today, band[2], hol)
        deadlines.append(deadline)
        a1 = week_end if week_end is not None and week_end <= deadline else deadline
        if typ == 'credit_card':
            label = 'credit card ending ' + str(it.get('card_last4') or '')
            floor = it.get('minimum_payment')
        else:
            label = 'car loan' if typ == 'car_loan' else 'personal loan'
            floor = it.get('instalment_amount')
        past = float(it.get('past_due') or 0)
        fl = float(floor or 0)
        ref = str(it.get('account_ref') or '')
        stmt.append('Your ' + label + ' has ' + money(past) + ' past due and is ' + str(days) + ' days late.')
        b = ['PRODUCT ' + str(n) + ': ' + label + ' (account_ref ' + ref + ')',
             '- Full past-due amount: ' + money(past) + ' (amount_cents ' + str(to_cents(past)) + '). Floor (lowest amount allowed): ' + money(fl) + ' (amount_cents ' + str(to_cents(fl)) + '). Any amount from the floor to the full amount, both included, can be accepted.',
             '- Days late: ' + str(days) + ', band ' + band[4] + ', persuasion attempts allowed: ' + str(band[3]) + '.',
             '- Deadline: ' + spoken_date(deadline) + ' (' + deadline.isoformat() + '). A promise date must be a business day from today to the deadline.',
             '- Attempt 1 (full amount): Could you pay the full ' + money(past) + ' for your ' + label + ' on ' + spoken_date(a1) + '?',
             '- Attempt 1 (if the customer already said the full amount is too much): Could you pay ' + money(fl) + ' for your ' + label + ' on ' + spoken_date(a1) + '? The rest stays overdue.']
        if band[3] >= 2:
            b.append('- Attempt 2: Could you pay ' + money(fl) + ' for your ' + label + ' on ' + spoken_date(deadline) + '? The rest stays overdue.')
        else:
            b.append('- No attempt 2 for this product: after attempt 1 is refused, stop.')
        b.append('- Full amount too much (offer once): I can record ' + money(fl) + ' for your ' + label + '. The rest stays overdue. Can you pay that?')
        b.append('- Amount below the floor: I cannot record less than ' + money(fl) + ' for your ' + label + '. Could you pay ' + money(fl) + '? The rest stays overdue.')
        b.append('- Date after the deadline: The latest date I can record for your ' + label + ' is ' + spoken_date(deadline) + '. Could you pay on that day?')
        b.append('- Read-back: your ' + label + ', <amount>, on <date>. Do you confirm?')
        blocks.append('\n'.join(b))
        lim[ref] = dict(floor=to_cents(fl), past=to_cents(past), deadline=deadline.isoformat(), deadline_spoken=spoken_date(deadline), label=label, floor_text=money(fl), past_text=money(past))
    vars['limits_json'] = json.dumps(dict(today=today.isoformat(), hol=HOL, p=lim))
    rows = []
    last = max(deadlines) if deadlines else today
    d = today
    while d <= last + datetime.timedelta(days=3):
        if is_business_day(d, hol):
            ok = [str(i + 1) for i, x in enumerate(deadlines) if d <= x]
            rows.append(d.isoformat() + ' ' + spoken_date(d) + ': business day; allowed for product ' + (', '.join(ok) if ok else 'none (after every deadline)'))
        else:
            rows.append(d.isoformat() + ' ' + spoken_date(d) + ': NOT a business day; offer the next business day, ' + spoken_date(next_business_day(d, hol)) + ', if it is not after the deadline')
        d = d + datetime.timedelta(days=1)
    mon = week_monday(today)
    wk = []
    for i, name in enumerate(WEEKDAYS):
        wk.append('this ' + name + ' = ' + spoken_date(mon + datetime.timedelta(days=i)) + '; next ' + name + ' = ' + spoken_date(mon + datetime.timedelta(days=7 + i)))
    first_q = 'Can you make this payment today?' if len(items) <= 1 else 'Can you pay all of them today?'
    vars['statement_text'] = 'I am calling from the collections team about a late payment. ' + ' '.join(stmt) + ' ' + first_q
    vars['facts_text'] = ('Today is ' + spoken_date(today) + ' (' + today.isoformat() + '). Products, in this order:\n' + '\n\n'.join(blocks) +
                          '\n\nDATE TABLE (a date before today is not allowed):\n' + '\n'.join(rows) +
                          '\n\nWEEKDAY WORDS (next = the following calendar week, this = the current week):\n' + '\n'.join(wk))
    vars['product_count'] = str(len(items))
    vars['facts_state'] = 'ok' if items else 'empty'
except Exception:
    vars['statement_text'] = 'I am calling from the collections team about a late payment. I am sorry, I cannot see the details right now.'
    vars['facts_text'] = 'The account details could not be read. Say you do not have that information.'
    vars['product_count'] = '0'
    vars['facts_state'] = 'error'
vars['close_outcome'] = 'no_promise'
vars['close_reason'] = 'refused'
